def score_shard(shard, gold, models):
    """Build result rows for one shard. Returns list of DB tuples."""
    rows_by_model = {}
    for row in read_jsonl(PREDICTIONS_DIR / f"{shard}.jsonl"):
        eid = row["example_id"]
        if eid not in gold:
            continue  # stray id: contributes nothing (SPEC 3.4)
        if shard_of(eid) != shard:
            continue
        per_model = rows_by_model.setdefault(row["model"], {})
        if eid in per_model:
            continue  # duplicate: first occurrence wins (SPEC 3.3)
        per_model[eid] = row["label"]

    shard_gold = {eid: g for eid, g in gold.items() if shard_of(eid) == shard}
    out = []
    for model in sorted(models):
        preds = rows_by_model.get(model, {})
        for eid in sorted(shard_gold):
            raw = preds.get(eid)
            if raw is None:
                final = None  # missing prediction: INVALID (SPEC 3.2)
            else:
                final = normalize_label(raw)
                if final not in CATEGORY_WEIGHTS:
                    final = None  # non-taxonomy label: INVALID (SPEC 3.1)
            out.append((model, eid, shard, shard_gold[eid], raw, final))
    return out


def expected_rows_by_shard(gold, models):
    expected = {}
    for shard in SHARDS:
        n_gold = sum(1 for eid in gold if shard_of(eid) == shard)
        expected[shard] = n_gold * len(models)
    return expected


def shard_row_counts(conn):
    return {
        shard: (count, distinct_pairs)
        for shard, count, distinct_pairs in conn.execute(
            "SELECT shard, COUNT(*), COUNT(DISTINCT model || char(0) || example_id) "
            "FROM results GROUP BY shard"
        )
    }


def resume_plan(conn, gold, models):
    """Return shards whose persisted rows do not match a completed shard."""
    expected = expected_rows_by_shard(gold, models)
    actual = shard_row_counts(conn)
    return [shard for shard in SHARDS if actual.get(shard, (0, 0)) != (expected[shard], expected[shard])]


def run(resume=False, log=print):
    gold = load_gold()
    models = load_models(gold)
    state = checkpoint.load()
    conn = connect()
    if resume:
        plan = resume_plan(conn, gold, models)
        state = {
            "completed": [s for s in SHARDS if s not in plan],
            "in_progress": None,
        }
        checkpoint.save(state)
        log(f"resume: {len(state['completed'])} shards verified done")
    else:
        reset_db(conn)
        state = {"completed": [], "in_progress": None}
        checkpoint.save(state)
        plan = list(SHARDS)
        log(f"fresh run: scoring {len(plan)} shards")
    for shard in plan:
        checkpoint.set_in_progress(state, shard)
        rows = score_shard(shard, gold, models)
        insert_rows(conn, rows)
        checkpoint.mark_done(state, shard)
        log(f"{shard}: committed {len(rows)} rows")
    conn.close()
    log("scoring complete")


def main(argv=None):
    ap = argparse.ArgumentParser()
    ap.add_argument("--resume", action="store_true")
    args = ap.parse_args(argv)
    run(resume=args.resume)


if __name__ == "__main__":
    sys.exit(main())
